def zoh_basis(log_I, log_c, t_force, tau, t_s, query):
    """Exact solution of I q'' + c q' = tau (ZOH, tau_k on [t_k, t_k+1), tau_0 before t_0) from q=0 at t_s.
    Returns (forced response from rest at t_s, unit-initial-velocity response) at `query` (>= t_s).
    log_I/log_c may carry a batch dimension [B]."""
    I, c = torch.exp(log_I)[..., None], torch.exp(log_c)[..., None]
    a = c / I
    k = int(torch.searchsorted(t_force, torch.as_tensor(t_s, dtype=DT), right=True)) - 1
    after = t_force > t_s
    knots = torch.cat([torch.as_tensor([t_s], dtype=DT), t_force[after]])
    held = torch.cat([tau[max(k, 0):max(k, 0) + 1], tau[after]])            # held[j] on [knots_j, knots_j+1)
    h = torch.diff(knots)
    vinf = held / c                                                          # [B, K]
    e = torch.exp(-a * h)
    ah = a * h
    phi = torch.where(ah > 1e-6, (1 - e) / a, h * (1 - 0.5 * ah))
    v = torch.zeros_like(a[..., 0]); q = torch.zeros_like(a[..., 0])
    qs, vs = [q], [v]
    for j in range(h.numel()):
        q = q + vinf[..., j] * h[j] + (v - vinf[..., j]) * phi[..., j]
        v = vinf[..., j] + (v - vinf[..., j]) * e[..., j]
        qs.append(q); vs.append(v)
    Q, V = torch.stack(qs, -1), torch.stack(vs, -1)
    idx = torch.clamp(torch.searchsorted(knots, query, right=True) - 1, 0, knots.numel() - 1)
    dt = query - knots[idx]
    vq = held[..., idx] / c if held.dim() > 1 else held[idx] / c
    eq = torch.exp(-a * dt)
    phiq = torch.where(a * dt > 1e-6, (1 - eq) / a, dt * (1 - 0.5 * a * dt))
    forced = Q[..., idx] + vq * dt + (V[..., idx] - vq) * phiq
    tq = query - t_s
    free = torch.where(a * tq > 1e-6, (1 - torch.exp(-a * tq)) / a, tq * (1 - 0.5 * a * tq))
    return forced, free

def _ls_offset_velocity(forced, free, qo):
    """Closed-form least squares for q = off + v0 * free + forced (batched)."""
    r = qo - forced                                                         # [B, N]
    n = r.shape[-1]
    s1, sf, sff = n, free.sum(-1), (free * free).sum(-1)
    sr, sfr = r.sum(-1), (free * r).sum(-1)
    det = s1 * sff - sf * sf
    v0 = (s1 * sfr - sf * sr) / det
    off = (sr - v0 * sf) / s1
    return off, v0

